import type { ChapterGuide } from '../../learning-types';
import { foundationGuides } from '../foundations-guides';

// Mathematics is language-neutral and shared verbatim. Every visible narrative
// field is authored below; no Chinese prose is used as a translation fallback.
type GuideText = Omit<ChapterGuide, 'chapterId' | 'symbols' | 'steps'> & {
  symbols: Omit<ChapterGuide['symbols'][number], 'symbol'>[];
  steps: Omit<ChapterGuide['steps'][number], 'formula'>[];
};
function translatedGuide(chapterId: string, text: GuideText): ChapterGuide {
  const mathematicalSource = foundationGuides.find(guide => guide.chapterId === chapterId);
  if (!mathematicalSource || text.steps.length !== mathematicalSource.steps.length || text.symbols.length !== mathematicalSource.symbols.length) {
    throw new Error(`Incomplete English foundation guide ${chapterId}`);
  }
  return {
    chapterId,
    ...text,
    symbols: text.symbols.map((symbol, index) => ({ ...symbol, symbol: mathematicalSource.symbols[index].symbol })),
    steps: text.steps.map((step, index) => ({ ...step, formula: mathematicalSource.steps[index].formula })),
  };
}

